grid = [[4]*13 for _ in range(20)]
markers=[(1,2),(1,9),(6,11),(7,4),(12,2),(13,11),(17,4),(17,8)]
# Existing 3x3 motif, centered on its middle cell (r12,c7).
pattern=[[4,5,5],[8,5,8],[8,5,0]]
# Seed background and source motif.
for dr in range(-1,2):
    for dc in range(-1,2):
        val=pattern[dr+1][dc+1]
        if val != 4:
            grid[12+dr][7+dc]=val
# Stamp motif centered on each 1 marker.
for r,c in markers:
    for dr in range(-1,2):
        for dc in range(-1,2):
            val=pattern[dr+1][dc+1]
            if val != 4:
                grid[r+dr][c+dc]=val
print(grid)
print('\n'.join(' '.join(map(str,row)) for row in grid))
